"""Reports the generated files that are out of date with the sources they are generated from.

Not every generated file has the same owner:

  * The Grasshopper component reference (docs/grasshopper-components/components.js) and the Python
    client (python-client/tapir_archicad/commands.py) are written by a script and committed, and no
    release job rewrites them. They have to be current in the pull request that changes their
    sources, or the site and the package describe an older plugin than the one in the repository.
  * The command reference and the AI files (docs/archicad-addon/*.js, docs/commands*, docs/llms*,
    docs/sitemap.xml) are regenerated by the weekly release, by design, so a pull request may leave
    them a week behind. This script does not fail on them; --all reports them, for a maintainer
    running the release by hand.

Which side of a disagreement is right is not decided here: tools/check_tool_settings.py reports the
tool settings tables that disagree with the Add-On's schema, and how many is all this script says.

Usage:
  python tools/check_drift.py            check the files a pull request must have current
  python tools/check_drift.py --write    regenerate them, so the next run is clean
  python tools/check_drift.py --all      also the files the weekly release regenerates (slow)
  python tools/check_drift.py --strict   fail on the warnings too

Exit code: 1 when a file that must be current is not, 0 otherwise. On GitHub Actions the findings
are also written as error and warning annotations, so they show up on the pull request.
"""

import argparse
import os
import subprocess
import sys

REPO_ROOT = os.path.dirname (os.path.dirname (os.path.abspath (__file__)))

# Findings are printed for the log and, on GitHub Actions, as annotations.
ANNOTATE = os.environ.get ('GITHUB_ACTIONS') == 'true'


class Step:
    """One generator or checker: what it needs to run, and what it writes."""

    def __init__ (self, name, command, outputs = (), severity = 'error', why = ''):
        self.name = name
        self.command = command
        self.outputs = [os.path.join (REPO_ROOT, output) for output in outputs]
        self.severity = severity
        self.why = why


def Run (command):
    """Runs a generator or checker in the repository root; returns (ok, output)."""
    result = subprocess.run (
        [sys.executable] + command,
        cwd = REPO_ROOT,
        capture_output = True,
        text = True,
        encoding = 'utf-8',
        errors = 'replace')
    output = (result.stdout or '') + (result.stderr or '')
    return result.returncode == 0, output


def Read (path):
    """The bytes of a file, or None when it does not exist."""
    try:
        with open (path, 'rb') as f:
            return f.read ()
    except OSError:
        return None


def Write (path, content):
    with open (path, 'wb') as f:
        f.write (content)


def CheckGenerator (step, write):
    """Runs a generator and compares what it wrote with what was committed."""
    before = {path: Read (path) for path in step.outputs}
    ok, output = Run (step.command)
    if not ok:
        # The generator itself failed: report what it said, and put the files back.
        for path, content in before.items ():
            if content is not None:
                Write (path, content)
        return 'failed', output

    changed = [path for path in step.outputs if Read (path) != before[path]]
    if write:
        return ('regenerated', changed) if changed else ('current', changed)

    # --check: the files are put back, so a run of this script never leaves the tree dirty.
    for path, content in before.items ():
        if content is not None:
            Write (path, content)
    return ('drift', changed) if changed else ('current', changed)


def CheckCommand (step):
    """Runs a checker script and takes its exit code and output as the finding."""
    ok, output = Run (step.command)
    return ('current', output) if ok else ('drift', output)


def Annotate (level, title, message):
    if ANNOTATE:
        first = message.strip ().split ('\n')[0]
        print ('::%s title=%s::%s' % (level, title, first.replace ('%', '%25').replace ('\r', '%0D').replace ('\n', '%0A')))


def Relative (path):
    return os.path.relpath (path, REPO_ROOT).replace (os.sep, '/')


def Main ():
    parser = argparse.ArgumentParser (description = 'Report generated files that are out of date.')
    parser.add_argument ('--write', action = 'store_true', help = 'regenerate the files instead of only reporting them')
    parser.add_argument ('--all', action = 'store_true', help = 'also check the files the weekly release regenerates (slow)')
    parser.add_argument ('--strict', action = 'store_true', help = 'fail on warnings too')
    args = parser.parse_args ()

    # Files no release job rewrites: a pull request has to keep them current.
    steps = [
        Step (
            'Grasshopper component reference',
            ['tools/generate_gh_docs.py'],
            ['docs/grasshopper-components/components.js'],
            'error',
            'written by tools/generate_gh_docs.py from the component classes'),
        Step (
            'Python client',
            ['python-client/generate.py'],
            ['python-client/tapir_archicad/commands.py'],
            'error',
            'written by python-client/generate.py from the command reference'),
        Step (
            'Examples',
            ['tools/check_examples.py'],
            [],
            'error',
            'one example per command, shown by the command reference'),
        Step (
            'Marketplace',
            ['tools/check_marketplace.py'],
            [],
            'error',
            'the listings against marketplace/README.md'),
    ]

    if args.all:
        # Regenerated by the weekly release (see the top of this file), so only reported.
        steps += [
            Step (
                'Command reference',
                ['tools/generate_addon_docs.py'],
                ['docs/archicad-addon/command_definitions.js', 'docs/archicad-addon/common_schema_definitions.js'],
                'warning',
                'regenerated by the weekly release'),
            Step (
                'AI files',
                ['tools/generate_llm_files.py'],
                ['docs/commands.json', 'docs/commands.md', 'docs/llms.txt', 'docs/llms-full.txt', 'docs/sitemap.xml'],
                'warning',
                'regenerated by the weekly release'),
            Step (
                'Grasshopper coverage',
                ['tools/generate_gh_coverage.py'],
                ['docs/gh-coverage/index.html'],
                'warning',
                'regenerated by the weekly release'),
        ]

    # Not checked by default: the tables against the Add-On's schema, where the two disagree and
    # the maintainer has to say which side is right. Reported, never failed on.
    steps.append (Step (
        'Tool settings tables',
        ['tools/check_tool_settings.py'],
        [],
        'warning',
        'tools/check_tool_settings.py reports settings the Add-On has and the tables do not'))

    failures = 0
    warnings = 0
    for step in steps:
        if step.outputs or not step.command[0].startswith ('tools/check'):
            status, detail = CheckGenerator (step, args.write)
        else:
            status, detail = CheckCommand (step)

        if status == 'current':
            print ('ok      %s' % step.name)
            continue

        if status == 'failed':
            print ('FAILED  %s: %s did not run' % (step.name, ' '.join (step.command)))
            for line in detail.strip ().split ('\n')[-6:]:
                print ('        ' + line)
            Annotate ('error', step.name, 'The generator failed: ' + detail)
            failures += 1
            continue

        if status == 'regenerated':
            print ('wrote   %s: %s' % (step.name, ', '.join (Relative (path) for path in detail)))
            continue

        # drift
        if step.outputs:
            print ('DRIFT   %s (%s)' % (step.name, step.why))
            for path in detail:
                print ('        ' + Relative (path))
            Annotate ('error', step.name, 'Out of date: ' + ', '.join (Relative (path) for path in detail) + '. Run python tools/check_drift.py --write.')
        else:
            lines = [line for line in detail.strip ().split ('\n') if line.strip ()]
            print ('DRIFT   %s (%s): %d line(s) of findings' % (step.name, step.why, len (lines)))
            for line in lines[:10]:
                print ('        ' + line)
            if len (lines) > 10:
                print ('        ... and %d more' % (len (lines) - 10))
            Annotate ('warning', step.name, '%d finding(s), first: %s' % (len (lines), lines[0] if lines else ''))

        if step.severity == 'error':
            failures += 1
        else:
            warnings += 1

    print ()
    if failures:
        print ('%d file(s) that must be current are not. Run: python tools/check_drift.py --write' % failures)
    elif warnings:
        print ('Nothing that must be current is out of date; %d warning(s) above.' % warnings)
    else:
        print ('Everything that must be current is up to date.')

    return 1 if failures or (args.strict and warnings) else 0


if __name__ == '__main__':
    sys.exit (Main ())
